const cfg = $('Choose topics and limits').first().json;
const hours = Number(cfg.lookbackHours);
if (!Number.isFinite(hours) || hours <= 0) throw new Error('lookbackHours must be greater than zero');
const now = Date.now();
const articles = [], warnings = [], health = {};
const stats = {received: 0, invalid: 0, outsideWindow: 0, duplicates: 0, excluded: 0, belowScore: 0};
for (const item of $input.all()) {
  const r = item.json;
  const source = String(r.sourceId || 'unknown');
  health[source] ??= {items: 0, status: 'empty'};
  if (r.error) { health[source].status = 'failed'; warnings.push(source + ': could not read RSS. Check its execution output and URL.'); continue; }
  if (!r.title && !r.link) { warnings.push(source + ': empty feed.'); continue; }
  stats.received++;
  health[source].items++;
  health[source].status = 'ok';
  const title = String(r.title || '').replace(/<[^>]*>/g, '').replace(/\s+/g, ' ').trim();
  const rawUrl = String(r.link || '').trim();
  const parts = rawUrl.match(/^(https?):\/\/([a-z0-9.-]+)(?::([0-9]{1,5}))?(\/[^?#\s]*)?(?:\?([^#\s]*))?(?:#[^\s]*)?$/i);
  if (!parts || !parts[2].includes('.') || (parts[3] && Number(parts[3]) > 65535)) { stats.invalid++; continue; }
  const query = (parts[5] || '').split('&').filter(Boolean).filter(part => {
    let key;
    try { key = decodeURIComponent(part.split('=')[0]).toLowerCase(); } catch { return true; }
    return !key.startsWith('utm_') && !['fbclid','gclid'].includes(key);
  }).sort().join('&');
  const hostname = parts[2].toLowerCase();
  const url = parts[1].toLowerCase() + '://' + hostname + (parts[3] ? ':'+parts[3] : '') + (parts[4] || '/') + (query ? '?'+query : '');
  const time = Date.parse(r.isoDate || r.pubDate || r.published || '');
  if (!title || !Number.isFinite(time)) { stats.invalid++; continue; }
  const ageHours = (now - time) / 3600000;
  if (ageHours < -1 || ageHours > hours) { stats.outsideWindow++; continue; }
  articles.push({title: title.slice(0,500), url, publisher: hostname.replace(/^www\./,''), source, publishedAt: new Date(time).toISOString(), ageHours: Math.max(0,ageHours)});
}
return [{json: {articles, warnings: [...new Set(warnings)], health, stats}}];

const data = $input.first().json;
const links = new Set(), titles = new Set();
data.articles.sort((a,b) => b.publishedAt.localeCompare(a.publishedAt));
data.articles = data.articles.filter(a => {
  const title = a.title.toLowerCase().replace(/[^\p{L}\p{N}]+/gu,' ').trim();
  if (links.has(a.url) || titles.has(title)) {data.stats.duplicates++; return false;}
  links.add(a.url); titles.add(title); return true;
});
return [{json:data}];

const data = $input.first().json;
const cfg = $('Choose topics and limits').first().json;
const words = s => [...new Set(String(s || '').toLowerCase().split(',').map(x=>x.trim()).filter(Boolean))];
const topics = words(cfg.topics), excluded = words(cfg.excludeWords);
const minimum = Number(cfg.minimumScore);
if (!Number.isFinite(minimum) || minimum < 0 || minimum > 100) throw new Error('minimumScore must be 0 to 100');
const normalize = s => s.toLowerCase().replace(/[^\p{L}\p{N}]+/gu,' ').trim();
const matches = (title, term) => (' '+normalize(title)+' ').includes(' '+normalize(term)+' ');
data.articles = data.articles.filter(a => {
  if (excluded.some(w => matches(a.title,w))) {data.stats.excluded++; return false;}
  const hits = topics.filter(w=>matches(a.title,w));
  if (topics.length && !hits.length) {data.stats.belowScore++; return false;}
  const freshness = a.ageHours <= 6 ? 40 : a.ageHours <= 24 ? 25 : 10;
  a.score = Math.min(100, hits.length * 20 + freshness);
  a.reason = (hits.length ? 'Topics: '+hits.join(', ') : 'All topics enabled') + '; freshness +'+freshness;
  if (a.score < minimum) {data.stats.belowScore++; return false;}
  return true;
});
return [{json:data}];

const data = $input.first().json;
const cfg = $('Choose topics and limits').first().json;
const max = Number(cfg.maxStories), cap = Number(cfg.maxPerSource);
if (![max,cap].every(n=>Number.isInteger(n)&&n>0&&n<=100)) throw new Error('Story limits must be integers from 1 to 100');
const counts = {};
data.stats.qualified = data.articles.length;
data.articles.sort((a,b)=>b.score-a.score || b.publishedAt.localeCompare(a.publishedAt));
data.articles = data.articles.filter(a=>{
  counts[a.publisher] ??= 0;
  if (counts[a.publisher]>=cap) return false;
  counts[a.publisher]++; return true;
}).slice(0,max);
data.stats.selected = data.articles.length;
data.generatedAt = new Date().toISOString();
data.status = Object.values(data.health).every(h=>h.status==='failed') ? 'all_feeds_failed' : data.articles.length ? 'ready' : 'no_matches';
return [{json:data}];

const data = $input.first().json;
const escape = x => String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const rows = data.articles.map((a,i)=>`<article><div class="meta">${i+1} · ${escape(a.publisher)} · score ${a.score}</div><h2><a href="${escape(a.url)}" rel="noopener noreferrer">${escape(a.title)}</a></h2><p>${escape(a.reason)}</p><small>Published ${escape(a.publishedAt)}</small></article>`).join('');
const health = Object.entries(data.health).map(([name,h])=>`<li>${escape(name)}: ${escape(h.status)} (${h.items} items)</li>`).join('');
const warnings = data.warnings.map(w=>`<li>${escape(w)}</li>`).join('');
const empty = data.status === 'all_feeds_failed' ? 'All feeds failed. Check the RSS node outputs and configured URLs.' : 'No matching stories in this time window. Try broader keywords or a longer lookback.';
const html = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Topic Radar</title><style>body{font:16px/1.6 system-ui,sans-serif;background:#f3f5f9;color:#172337;margin:0}main{max-width:850px;margin:auto;padding:36px 20px}h1{font-size:36px;margin:0}h2{font-size:21px;margin:8px 0}a{color:#1259a7}article,section{background:white;border:1px solid #dce3ec;border-radius:12px;padding:20px;margin:18px 0}.meta,small{color:#52657b}p{margin:8px 0}</style></head><body><main><h1>Topic Radar</h1><p>Editorial shortlist · ${escape(data.generatedAt)}</p><p>${data.stats.received} received · ${data.stats.duplicates} duplicates · ${data.stats.selected} selected</p>${rows || '<section>'+escape(empty)+'</section>'}<section><h2>Source health</h2><ul>${health}</ul>${warnings ? '<ul>'+warnings+'</ul>':''}<p>Skipped: ${data.stats.invalid} invalid, ${data.stats.outsideWindow} outside time window, ${data.stats.excluded} excluded, ${data.stats.belowScore} unmatched or below score.</p></section><p>Read the original source before writing. Scores measure configured topic relevance and freshness, not accuracy or likely reach. This is a rolling snapshot; stories can reappear in later runs.</p></main></body></html>`;
return [{json:{...data,html}}];
